mapper.insert:

    SELECT  PROJECT_EXPERIENCE_SEQ.NEXTVAL
    FROM    DUAL

INSERT INTO PROJECT_EXPERIENCE (
    PROJECT_ID
   ,MEMBER_ID
   ,PROJECT_NAME
   ,ORGANIZATION
   ,ROLE_NAME
   ,START_DATE
   ,END_DATE
   ,DESCRIPTION
   ,PROJECT_URL
   ,CREATED_AT
   ,UPDATED_AT
) VALUES (
    #{projectId}
   ,#{memberId}
   ,#{projectName}
   ,#{organization,jdbcType=VARCHAR}
   ,#{roleName,jdbcType=VARCHAR}
   ,#{startDate,jdbcType=DATE}
   ,#{endDate,jdbcType=DATE}
   ,#{description,jdbcType=CLOB}
   ,#{projectUrl,jdbcType=VARCHAR}
   ,SYSTIMESTAMP
   ,SYSTIMESTAMP
)

mapper.update:
UPDATE  PROJECT_EXPERIENCE
SET     PROJECT_NAME = #{projectName}
       ,ORGANIZATION = #{organization,jdbcType=VARCHAR}
       ,ROLE_NAME    = #{roleName,jdbcType=VARCHAR}
       ,START_DATE   = #{startDate,jdbcType=DATE}
       ,END_DATE     = #{endDate,jdbcType=DATE}
       ,DESCRIPTION  = #{description,jdbcType=CLOB}
       ,PROJECT_URL  = #{projectUrl,jdbcType=VARCHAR}
       ,UPDATED_AT   = SYSTIMESTAMP
WHERE   MEMBER_ID = #{memberId}
AND     PROJECT_ID = #{projectId}

mapper.delete:
